#!/usr/bin/env python3
"""
Reproduction script for the annotated types serialization strategy issue.
"""

from dataclasses import dataclass
from typing import Annotated, TypeAlias
from mashumaro import DataClassDictMixin


# Define our annotated types
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]


def deserialize_positive_int(value):
    print(f"Deserializing positive int: {value}")
    if value < 0:
        raise ValueError("value < 0")
    return value


def deserialize_negative_int(value):
    print(f"Deserializing negative int: {value}")
    if value >= 0:
        raise ValueError("value >= 0")
    return value


def serialize_positive_int(value):
    print(f"Serializing positive int: {value}")
    if value < 0:
        raise ValueError("value < 0")
    return value


def serialize_negative_int(value):
    print(f"Serializing negative int: {value}")
    if value >= 0:
        raise ValueError("value >= 0")
    return value


@dataclass
class MyClass(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
                "serialize": serialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
                "serialize": serialize_negative_int,
            }
        }


def test_annotated_serialization_strategy():
    """Test that annotated types can have different serialization strategies."""
    print("Testing annotated types serialization strategy...")

    # Create an instance
    obj = MyClass(positive_int=5, negative_int=-3)
    print(f"Created object: {obj}")

    # Serialize to dict
    print("\n--- Serializing ---")
    try:
        serialized = obj.to_dict()
        print(f"Serialized: {serialized}")
    except Exception as e:
        print(f"Serialization error: {e}")
        return False

    # Deserialize from dict
    print("\n--- Deserializing ---")
    try:
        data = {"positive_int": 10, "negative_int": -7}
        restored = MyClass.from_dict(data)
        print(f"Restored: {restored}")
        return True
    except Exception as e:
        print(f"Deserialization error: {e}")
        return False


if __name__ == "__main__":
    success = test_annotated_serialization_strategy()
    if success:
        print("\n✅ Test passed!")
    else:
        print("\n❌ Test failed!")

