"""
Comprehensive test for annotated types serialization strategy issue.
Tests both serialization and deserialization.
"""

from dataclasses import dataclass
from typing import Annotated
from typing_extensions import TypeAlias
from mashumaro import DataClassDictMixin


# Global flags to track if our custom functions are called
serialization_called = {"positive": False, "negative": False}
deserialization_called = {"positive": False, "negative": False}


# Define our annotated types
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]


def deserialize_positive_int(value):
    print(f"Deserializing positive int: {value}")
    deserialization_called["positive"] = True
    if value < 0:
        raise ValueError("value < 0")
    return value


def deserialize_negative_int(value):
    print(f"Deserializing negative int: {value}")
    deserialization_called["negative"] = True
    if value >= 0:
        raise ValueError("value >= 0")
    return value


def serialize_positive_int(value):
    print(f"Serializing positive int: {value}")
    serialization_called["positive"] = True
    if value < 0:
        raise ValueError("value < 0")
    # Return a string to show our function was called
    return f"POSITIVE:{value}"


def serialize_negative_int(value):
    print(f"Serializing negative int: {value}")
    serialization_called["negative"] = True
    if value >= 0:
        raise ValueError("value >= 0")
    # Return a string to show our function was called
    return f"NEGATIVE:{value}"


@dataclass
class MyClass(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
                "serialize": serialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
                "serialize": serialize_negative_int,
            }
        }


def test_both_directions():
    """Test that both serialization and deserialization work with annotated types."""
    global serialization_called, deserialization_called

    print("=== Testing Annotated Types Serialization Strategy ===")

    # Reset flags
    serialization_called = {"positive": False, "negative": False}
    deserialization_called = {"positive": False, "negative": False}

    # Test 1: Deserialization
    print("\n1. Testing Deserialization:")
    try:
        data = {"positive_int": 10, "negative_int": -7}
        obj = MyClass.from_dict(data)
        print(f"   Created: {obj}")

        # Check if custom deserialization was called
        if deserialization_called["positive"] and deserialization_called["negative"]:
            print("   ✅ Custom deserialization functions were called")
        else:
            print("   ❌ Custom deserialization functions were NOT called")

    except Exception as e:
        print(f"   ❌ Deserialization failed: {e}")
        return False

    # Test 2: Serialization
    print("\n2. Testing Serialization:")
    try:
        serialized = obj.to_dict()
        print(f"   Serialized: {serialized}")

        # Check if custom serialization was called (we should see our custom strings)
        pos_val = serialized.get("positive_int")
        neg_val = serialized.get("negative_int")

        if isinstance(pos_val, str) and pos_val.startswith("POSITIVE:"):
            print("   ✅ Custom positive serialization function was called")
        else:
            print("   ❌ Custom positive serialization function was NOT called")

        if isinstance(neg_val, str) and neg_val.startswith("NEGATIVE:"):
            print("   ✅ Custom negative serialization function was called")
        else:
            print("   ❌ Custom negative serialization function was NOT called")

        # Also check the flags
        if serialization_called["positive"] and serialization_called["negative"]:
            print("   ✅ Serialization called flags are set")
        else:
            print("   ❌ Serialization called flags are NOT set")

    except Exception as e:
        print(f"   ❌ Serialization failed: {e}")
        return False

    # Summary
    print("\n3. Summary:")
    deserial_ok = deserialization_called["positive"] and deserialization_called["negative"]
    serial_ok = serialization_called["positive"] and serialization_called["negative"]

    if deserial_ok and serial_ok:
        print("   ✅ Both serialization and deserialization work correctly")
        return True
    elif deserial_ok and not serial_ok:
        print("   ⚠️  Deserialization works but serialization doesn't")
        return False
    elif not deserial_ok and serial_ok:
        print("   ⚠️  Serialization works but deserialization doesn't")  
        return False
    else:
        print("   ❌ Neither serialization nor deserialization work correctly")
        return False


if __name__ == "__main__":
    success = test_both_directions()
    if success:
        print("\n🎉 All tests passed!")
    else:
        print("\n💥 Some tests failed!")
        exit(1)

