#!/usr/bin/env python3
"""
Test for annotated types serialization strategy functionality.
This test can be added to the official test suite.
"""

from dataclasses import dataclass
from typing import Annotated
from typing_extensions import TypeAlias

from mashumaro import DataClassDictMixin


def test_annotated_serialization_strategy():
    """Test that annotated types can have different serialization strategies for both directions."""

    # Define annotated types
    PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
    NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]

    # Custom serialization functions
    def deserialize_positive_int(value):
        if value < 0:
            raise ValueError("value must be positive")
        return value

    def deserialize_negative_int(value):
        if value >= 0:
            raise ValueError("value must be negative")
        return value

    def serialize_positive_int(value):
        if value < 0:
            raise ValueError("value must be positive")
        return f"POSITIVE:{value}"

    def serialize_negative_int(value):
        if value >= 0:
            raise ValueError("value must be negative")
        return f"NEGATIVE:{value}"

    @dataclass
    class MyClass(DataClassDictMixin):
        positive_int: PositiveInt
        negative_int: NegativeInt

        class Config:
            serialization_strategy = {
                PositiveInt: {
                    "deserialize": deserialize_positive_int,
                    "serialize": serialize_positive_int,
                },
                NegativeInt: {
                    "deserialize": deserialize_negative_int,
                    "serialize": serialize_negative_int,
                }
            }

    # Test deserialization
    data = {"positive_int": 10, "negative_int": -7}
    obj = MyClass.from_dict(data)
    assert obj.positive_int == 10
    assert obj.negative_int == -7

    # Test serialization
    serialized = obj.to_dict()
    assert serialized == {"positive_int": "POSITIVE:10", "negative_int": "NEGATIVE:-7"}

    # Test error cases
    try:
        MyClass.from_dict({"positive_int": -5, "negative_int": -7})
        assert False, "Should have raised ValueError"
    except ValueError:
        pass  # Expected

    try:
        MyClass.from_dict({"positive_int": 10, "negative_int": 5})
        assert False, "Should have raised ValueError"
